const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tokens = lines.join(' ').trim().split(/\s+/).map(Number);
const n = tokens[0];
const cost = Array.from({ length: n }, (_, i) =>
  tokens.slice(1 + i * n, 1 + (i + 1) * n)
);

// Column 0 points to the row starting the current search.
const u = [0, ...cost.map(row => Math.min(...row))];
const v = Array(n + 1).fill(0);
const owner = Array(n + 1).fill(0);

for (let row = 1; row <= n; row++) {
  owner[0] = row;
  let column = 0;
  const used = Array(n + 1).fill(false);
  const slack = Array(n + 1).fill(Infinity);
  const previous = Array(n + 1).fill(0);
  do {
    used[column] = true;
    const current = owner[column];
    let delta = Infinity;
    let nextColumn = 0;
    for (let j = 1; j <= n; j++) {
      if (used[j]) continue;
      const reduced = cost[current - 1][j - 1] - u[current] - v[j];
      if (reduced < slack[j]) {
        slack[j] = reduced;
        previous[j] = column;
      }
      if (slack[j] < delta) {
        delta = slack[j];
        nextColumn = j;
      }
    }

    u[row] += delta;
    for (let j = 1; j <= n; j++) {
      if (used[j]) {
        u[owner[j]] += delta;
        v[j] -= delta;
      } else {
        slack[j] -= delta;
      }
    }
    column = nextColumn;
  } while (owner[column] !== 0);

  while (column !== 0) {
    const parent = previous[column];
    owner[column] = owner[parent];
    column = parent;
  }
}

let total = 0;
for (let j = 1; j <= n; j++) total += cost[owner[j] - 1][j - 1];
