                input.nextToken();
                cost[i][j] = (long) input.nval;
            }
        }

        long[] u = new long[n + 1];
        long[] v = new long[n + 1];
        int[] owner = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            u[i] = cost[i - 1][0];
            for (long value : cost[i - 1]) u[i] = Math.min(u[i], value);
        }

        // Column 0 points to the row starting the current search.
        for (int row = 1; row <= n; row++) {
            owner[0] = row;
            int column = 0;
            boolean[] used = new boolean[n + 1];
            long[] slack = new long[n + 1];
            Arrays.fill(slack, Long.MAX_VALUE / 4);
            int[] previous = new int[n + 1];
            do {
                used[column] = true;
                int current = owner[column];
                long delta = Long.MAX_VALUE / 4;
                int nextColumn = 0;
                for (int j = 1; j <= n; j++) {
                    if (used[j]) continue;
                    long reduced = cost[current - 1][j - 1] - u[current] - v[j];
                    if (reduced < slack[j]) {
                        slack[j] = reduced;
                        previous[j] = column;
                    }
                    if (slack[j] < delta) {
                        delta = slack[j];
                        nextColumn = j;
                    }
                }

                u[row] += delta;
                for (int j = 1; j <= n; j++) {
                    if (used[j]) {
                        u[owner[j]] += delta;
                        v[j] -= delta;
                    } else {
                        slack[j] -= delta;
                    }
                }
                column = nextColumn;
            } while (owner[column] != 0);

            while (column != 0) {
                int parent = previous[column];
                owner[column] = owner[parent];
                column = parent;
            }
        }

        long total = 0;
        for (int j = 1; j <= n; j++) total += cost[owner[j] - 1][j - 1];
        System.out.println(total);
    }
}

